FUNCTION UNDER TEST:
Name: buffer_trim_right
Signature: void buffer_trim_right(buffer_t *self)
Description: /**
 * @brief Removes trailing whitespace from the end of a buffer.
 *
 * Scans the buffer from the end and replaces any trailing whitespace
 * characters with null bytes, effectively trimming spaces, tabs, and
 * newlines from the right. The buffer is modified in-place and may be
 * shortened, but its capacity is unchanged.
 *
 * @param self Pointer to a buffer_t structure. Must not be NULL and must
 *             reference a valid, null-terminated buffer.
 *
 * @return None.
 *
 * @note The buffer's data is modified in-place. The logical length may
 *       decrease, but the underlying memory is not reallocated.
 *
 * @see buffer_length
 */
Dependencies: buffer_length

FUNCTION IMPLEMENTATION:
```c
// C program for the function called buffer_trim_right
// Contains target function implementation and dependency signatures

#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <ctype.h>
#include <sys/types.h>
#include "buffer.h"

// Forward declarations for dependency functions
size_t
buffer_length(buffer_t *self);

// Target function implementation
void
buffer_trim_right(buffer_t *self) {
  int c;
  size_t i = buffer_length(self) - 1;
  while ((c = self->data[i]) && isspace(c)) {
    self->data[i--] = 0;
  }
}

